const API=(window.APP_CONFIG?.apiBaseUrl||'').replace(/\/+$/,'')+'/api';let teachers=[],allTeachers=[],subjects=[],classes=[],selectedDay='SUNDAY',schoolSettings={school_name:'المدرسة',school_logo_url:null};let registrationAvailable=false,authMode='login',currentRole='MANAGER',pendingStaffInvite='';
const days={SUNDAY:'الأحد',MONDAY:'الإثنين',TUESDAY:'الثلاثاء',WEDNESDAY:'الأربعاء',THURSDAY:'الخميس'};const statusLabel={TEACHING:'تدريس',FREE:'فراغ',DUTY:'مناوبة',OTHER:'أخرى',SUGGESTED:'بانتظار الاختيار',ASSIGNED:'مكلف',CONFIRMED:'مؤكد',COMPLETED:'مكتمل',CANCELLED:'ملغى'};
let assistantHasTeacherProfile=false,assistantConversation=[];
async function req(path,opts={}){const r=await fetch(API+path,{credentials:'include',...opts});let data=null;try{data=await r.json()}catch{}if(r.status===401){showAuth(false);throw Error(typeof data?.detail==='string'?data.detail:'سجل الدخول للمتابعة')}if(!r.ok)throw Error(typeof data?.detail==='string'?data.detail:(data?.detail?.message||JSON.stringify(data?.detail)||'تعذر تنفيذ العملية'));return data}
function notify(message,error=false){const n=document.querySelector('#notice');n.textContent=message;n.className='notice'+(error?' error':'');n.setAttribute('role',error?'alert':'status');n.setAttribute('aria-live',error?'assertive':'polite');window.scrollTo({top:0,behavior:'smooth'});clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.classList.add('hidden'),5500)}
function loadingMarkup(label='جارٍ تحميل البيانات'){return `<div class="loading-state" role="status"><span class="loading-mark" aria-hidden="true"></span><span>${label}</span></div>`}
function retryMarkup(message,retry){return `<div class="load-error"><strong>تعذر تحميل البيانات</strong><p>${esc(message)}</p><button type="button" class="button secondary" data-retry>إعادة المحاولة</button></div>`}
function setLoadError(selector,error,retry){const target=document.querySelector(selector);target.innerHTML=retryMarkup(error.message||'حدث خطأ غير متوقع',retry);target.querySelector('[data-retry]').onclick=retry;target.setAttribute('aria-busy','false')}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function view(name){if(!canView(name))return notify("ليس لديك صلاحية لعرض هذه الصفحة",true);document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+name));document.querySelectorAll('.nav').forEach(x=>{const active=x.dataset.view===name;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});updatePageChrome(name);if(name==='dashboard')loadDashboard();if(name==='schedule')loadSchedule();if(name==='substitutions')loadAssignments();if(name==='teachers')loadTeachers();if(name==='reports')loadReport();if(name==='settings')loadSchoolSettings();if(name==='audit')loadAudit();if(name==='roles')loadRoles();if(name==='staff')loadStaff();if(name==='my-work')loadMyWork()}
document.querySelectorAll('.nav,[data-open]').forEach(x=>x.addEventListener('click',()=>view(x.dataset.view||x.dataset.open)));
async function refreshBase(){[allTeachers,subjects,classes]=await Promise.all([req('/teachers'),req('/subjects'),req('/classes')]);teachers=allTeachers.filter(x=>x.is_active);fillOptions()}
function renderPeriodOptions(){const root=document.querySelector('#period-checkboxes');const previous=new Map([...root.querySelectorAll('.period-row')].map(row=>[row.dataset.period,{checked:row.querySelector('input[type=checkbox]').checked,classId:row.querySelector('select').value}]));root.innerHTML=Array.from({length:7},(_,i)=>{const period=String(i+1),state=previous.get(period)||{};return `<div class="period-row" data-period="${period}"><label class="period-check"><input type="checkbox" value="${period}" ${state.checked?'checked':''}> الحصة ${period}</label><label class="period-class-label" ${state.checked?'':'hidden'}>الشعبة<select aria-label="شعبة الحصة ${period}"><option value="">حسب الجدول تلقائيًا</option>${classes.map(c=>`<option value="${c.id}" ${String(c.id)===state.classId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div>`}).join('');root.querySelectorAll('.period-row input[type=checkbox]').forEach(check=>check.addEventListener('change',()=>{check.closest('.period-row').querySelector('.period-class-label').hidden=!check.checked}))}
function fillOptions(){const options=(items,first='')=>first+items.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');const absence=document.querySelector('#absence-teacher');const previous=absence.value;absence.innerHTML=teachers.length?options(teachers,'<option value="">اختر المعلم الغائب</option>'):'<option value="">لا يوجد معلمون نشطون</option>';if(previous&&teachers.some(x=>String(x.id)===previous))absence.value=previous;absence.disabled=teachers.length===0;const hint=document.querySelector('#absence-teacher-hint');hint.textContent=teachers.length?`القائمة محدثة · ${teachers.length} معلم نشط`:'ما في معلمين بالقائمة. استورد ملف الجدول من صفحة الجدول الأسبوعي أو فعّل معلمًا من صفحة المعلمين.';hint.classList.toggle('empty-state',teachers.length===0);document.querySelector('#cell-teacher').innerHTML=options(teachers);document.querySelector('#teacher-subject').innerHTML=options(subjects,'<option value="">اختر التخصص</option>');document.querySelector('#cell-subject').innerHTML=options(subjects,'<option value="">—</option>');document.querySelector('#cell-class').innerHTML=options(classes,'<option value="">—</option>');document.querySelector('#cell-period').innerHTML=Array.from({length:7},(_,i)=>`<option value="${i+1}">الحصة ${i+1}</option>`).join('');renderPeriodOptions()}
async function loadDashboard(){if(!can("dashboard.view"))return;const readiness=document.querySelector('#dashboard-readiness');readiness.setAttribute('aria-busy','true');readiness.innerHTML=loadingMarkup('جارٍ قراءة مؤشرات اليوم');try{const[d,overview]=await Promise.all([req('/dashboard/today'),req('/dashboard/overview')]);renderReadiness(overview);readiness.setAttribute('aria-busy','false');document.querySelector('#stats').innerHTML=[['المعلمون الغائبون',d.total_absent_teachers],['الحصص المتأثرة',d.affected_periods],['تم إسنادها',d.assigned],['بانتظار الاختيار',d.pending]].map((x,i)=>`<div class="stat"><span>${x[0]}</span><strong>${x[1]}</strong><i class="stat-icon" aria-hidden="true">${uiIcon(['absent','calendar','check','clock'][i])}</i><small>${['غياب مسجل لليوم','حصص تحتاج إلى تغطية','تكليفات تم توزيعها','حصص تحتاج متابعة'][i]}</small></div>`).join('');document.querySelector('#today-list').innerHTML=table(d.assignments);document.querySelector('#workload').innerHTML=d.workload.length?d.workload.map(x=>`<div class="bar-row"><span>${esc(x.teacher)}</span><div class="bar"><i style="width:${Math.max(5,x.assignments/Math.max(...d.workload.map(y=>y.assignments))*100)}%"></i></div><b>${x.assignments}</b></div>`).join(''):'<div class="empty">لا توجد تكليفات اليوم</div>'}catch(e){setLoadError('#dashboard-readiness',e,loadDashboard);notify(e.message,true)}}
function renderReadiness(o){const ready=o.expected_slots>0&&o.missing_slots===0;const empty=o.active_teachers===0;const percent=Math.min(100,o.completion_percent);const title=ready?'الجدول الأسبوعي مكتمل':empty?'ابدأ بتحميل جدول المدرسة':'بقيت خانات تحتاج مراجعة';const detail=ready?'النظام جاهز لاقتراح معلم بديل من الفترات الحرة.':empty?'استورد ملف Excel أو CSV لإضافة المعلمين والحصص تلقائيًا.':`أُدخل ${o.configured_slots} من ${o.expected_slots} خانة متوقعة؛ أكمل الناقص حتى تكون اقتراحات الاحتياط أدق.`;const button=empty?'استيراد الجدول':'مراجعة الجدول';document.querySelector('#dashboard-readiness').innerHTML=`<div class="readiness-top"><div><p class="eyebrow">جاهزية بيانات المدرسة</p><h2>${title}</h2><p class="muted">${detail}</p></div><span class="status-pill ${ready?'ready':empty?'suggested':'busy'}">${ready?'جاهز':empty?'يحتاج إعداد':'قيد الإكمال'}</span></div><div class="readiness-progress" role="progressbar" aria-label="اكتمال الجدول" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><span style="width:${percent}%"></span></div><div class="readiness-footer"><div class="readiness-counts"><span><b>${o.active_teachers}</b> معلم</span><span><b>${o.classes}</b> شعبة</span><span><b>${o.subjects}</b> تخصص</span><span><b>${o.free_slots}</b> فترة فراغ</span></div><button class="button ${ready?'secondary':'primary'}" data-open-import>${button}</button></div>`}
document.querySelector('#dashboard-readiness').onclick=e=>{if(!e.target.closest('[data-open-import]'))return;view('schedule');const box=document.querySelector('#import-box');if(box){box.open=true;box.scrollIntoView({behavior:'smooth',block:'center'})}};
function table(rows){if(!rows?.length)return '<div class="empty">لا توجد سجلات بعد</div>';return `<div class="table-wrap"><table><thead><tr><th>الحصة</th><th>الفصل</th><th>المعلم الغائب</th><th>المعلم المكلف</th><th>الحالة</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.period_number}</td><td>${esc(x.school_class?.name||'—')}</td><td>${esc(x.absent_teacher?.name||'—')}</td><td>${esc(x.substitute_teacher?.name||'—')}</td><td><span class="status-pill ${x.status.toLowerCase()}">${statusLabel[x.status]||x.status}</span></td></tr>`).join('')}</tbody></table></div>`}
async function loadSchedule(){selectedDay=document.querySelector('#schedule-day').value;const target=document.querySelector('#schedule-table');target.setAttribute('aria-busy','true');target.innerHTML=loadingMarkup('جارٍ تحميل جدول اليوم');try{const entries=await req('/schedule?day='+selectedDay);const staff=allTeachers.length?allTeachers:await req('/teachers');const lookup=new Map(entries.map(e=>[`${e.teacher_id}-${e.period_number}`,e]));const byTeacher=new Map();entries.forEach(e=>{if(!byTeacher.has(e.teacher_id))byTeacher.set(e.teacher_id,[]);byTeacher.get(e.teacher_id).push(e)});target.innerHTML=`<table><thead><tr><th>المعلم</th>${Array.from({length:7},(_,i)=>`<th>الحصة ${i+1}</th>`).join('')}</tr></thead><tbody>${staff.filter(x=>x.is_active).map(t=>{const own=byTeacher.get(t.id)||[];const states=[...new Set(own.map(e=>e.status))].join(' ');return `<tr data-teacher-name="${esc(t.name)}" data-statuses="${states}" data-entry-count="${own.length}"><th>${esc(t.name)}</th>${Array.from({length:7},(_,i)=>{const c=lookup.get(`${t.id}-${i+1}`);const reservePriority=Number((c?.notes||'').match(/^RESERVE_PRIORITY:(\d+)$/)?.[1]||0);const text=c?`${reservePriority?`احتياط ح${reservePriority}`:statusLabel[c.status]}${c.school_class?.name?` · ${c.school_class.name}`:''}${c.subject?.name?` · ${c.subject.name}`:''}`:'غير مدخل';return `<td><button class="cell-edit" aria-label="تعديل حصة ${i+1} للمعلم ${esc(t.name)}" data-cell="${c?.id||''}" data-teacher="${t.id}" data-period="${i+1}"><span class="status-pill ${c?.status==='FREE'?'free':c?.status==='DUTY'?'duty':c?'busy':''}"><strong>${esc(c?.school_class?.name|| (reservePriority?`احتياط ح${reservePriority}`:statusLabel[c?.status]||'غير مدخل'))}</strong><small>${esc(c?.subject?.name|| (c?.status==='FREE'?(reservePriority?'أولوية الاحتياط':'متاح للتكليف'):c?'غير متاح للتكليف':'لم تُسجل حصة'))}</small></span></button></td>`}).join('')}</tr>`}).join('')}</tbody></table>`;target.setAttribute('aria-busy','false');document.querySelectorAll('#schedule-table [data-cell]').forEach(b=>b.onclick=()=>editCell(b,lookup));filterScheduleRows()}catch(e){setLoadError('#schedule-table',e,loadSchedule);notify(e.message,true)}}
function filterScheduleRows(){const query=document.querySelector('#schedule-search').value.trim().toLocaleLowerCase('ar');const status=document.querySelector('#schedule-status').value;const rows=[...document.querySelectorAll('#schedule-table tbody tr')];let shown=0;rows.forEach(row=>{const name=row.dataset.teacherName.toLocaleLowerCase('ar');const states=row.dataset.statuses.split(' ');const matchesName=name.includes(query);const matchesStatus=status==='ALL'||(status==='MISSING'?Number(row.dataset.entryCount)<7:states.includes(status));row.hidden=!(matchesName&&matchesStatus);if(!row.hidden)shown++});document.querySelector('#schedule-count').textContent=`عرض ${shown} من ${rows.length} معلم`}
document.querySelector('#schedule-search').oninput=filterScheduleRows;document.querySelector('#schedule-status').onchange=filterScheduleRows;
function editCell(btn,lookup){if(!can("schedule.edit"))return;const id=btn.dataset.cell;const item=id?[...lookup.values()].find(x=>String(x.id)===id):null;document.querySelector('#cell-id').value=id;document.querySelector('#cell-teacher').value=item?.teacher_id||btn.dataset.teacher;document.querySelector('#cell-day').value=item?.day_of_week||selectedDay;document.querySelector('#cell-period').value=item?.period_number||btn.dataset.period;document.querySelector('#cell-status').value=item?.status||'FREE';document.querySelector('#cell-class').value=item?.class_id||'';document.querySelector('#cell-subject').value=item?.subject_id||'';document.querySelector('#delete-cell').style.display=id?'':'none';document.querySelector('#cell-dialog').showModal()}
document.querySelector('#schedule-day').onchange=loadSchedule;document.querySelector('#add-cell').onclick=()=>editCell({dataset:{cell:'',teacher:teachers[0]?.id||'',period:'1'}},new Map());
document.querySelector('#cell-form').onsubmit=async e=>{e.preventDefault();const id=document.querySelector('#cell-id').value;const body={teacher_id:+document.querySelector('#cell-teacher').value,day_of_week:document.querySelector('#cell-day').value,period_number:+document.querySelector('#cell-period').value,status:document.querySelector('#cell-status').value,class_id:+document.querySelector('#cell-class').value||null,subject_id:+document.querySelector('#cell-subject').value||null};try{await req('/schedule'+(id?'/'+id:''),{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});document.querySelector('#cell-dialog').close();loadSchedule();notify('تم حفظ خلية الجدول')}catch(e){notify(e.message,true)}};
document.querySelector('#delete-cell').onclick=async()=>{const id=document.querySelector('#cell-id').value;if(!id)return;try{await req('/schedule/'+id,{method:'DELETE'});document.querySelector('#cell-dialog').close();loadSchedule();notify('تم مسح الخلية')}catch(e){notify(e.message,true)}};
document.querySelector('#absence-date').value=new Date().toISOString().slice(0,10);document.querySelector('#report-date').value=new Date().toISOString().slice(0,10);
function dayForDate(value){const d=new Date(`${value}T12:00:00`);return ['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'][d.getDay()]}
async function autoSelectTeacherPeriods(){const teacherId=Number(document.querySelector('#absence-teacher').value),date=document.querySelector('#absence-date').value;if(!teacherId||!date)return;const day=dayForDate(date);if(!days[day])return notify('الجمعة والسبت خارج أيام الدوام المدرسي.',true);try{const entries=await req('/schedule?day='+day);const rows=[...document.querySelectorAll('#period-checkboxes .period-row')];rows.forEach(row=>{row.querySelector('input[type=checkbox]').checked=false;row.querySelector('.period-class-label').hidden=true;row.querySelector('select').value=''});entries.filter(x=>x.teacher_id===teacherId&&x.status==='TEACHING').forEach(entry=>{const row=document.querySelector(`#period-checkboxes .period-row[data-period="${entry.period_number}"]`);if(!row)return;row.querySelector('input[type=checkbox]').checked=true;row.querySelector('.period-class-label').hidden=false;if(entry.class_id)row.querySelector('select').value=String(entry.class_id)});if(!entries.some(x=>x.teacher_id===teacherId&&x.status==='TEACHING'))notify('ما لقيت حصص تدريس لهذا المعلم في هذا اليوم؛ تقدر تحدد الحصص يدويًا.',true)}catch(e){notify(e.message,true)}}
document.querySelector('#absence-teacher').addEventListener('change',autoSelectTeacherPeriods);document.querySelector('#absence-date').addEventListener('change',()=>{if(document.querySelector('#absence-teacher').value)autoSelectTeacherPeriods()});
document.querySelector('#absence-form').onsubmit=async e=>{e.preventDefault();const periods=[...document.querySelectorAll('#period-checkboxes .period-row')].filter(row=>row.querySelector('input[type=checkbox]').checked).map(row=>({period_number:+row.dataset.period,class_id:Number(row.querySelector('select').value)||null}));if(!periods.length)return notify('حدد حصة واحدة على الأقل',true);const payload={teacher_id:+document.querySelector('#absence-teacher').value,date:document.querySelector('#absence-date').value,reason:document.querySelector('#absence-reason').value||null,periods};try{const result=await req('/absences',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});renderRecommendations(result);document.querySelectorAll('#period-checkboxes .period-row').forEach(row=>{row.querySelector('input[type=checkbox]').checked=false;row.querySelector('.period-class-label').hidden=true;row.querySelector('select').value=''});loadAssignments();notify(can('substitutions.manage')?'تم تسجيل الغياب. راجع المرشحين واختر المعلم المناسب.':'تم تسجيل الغياب وأضيفت الحصص إلى سجل التكليفات.')}catch(e){notify(e.message,true)}};
function renderRecommendations(result){if(!can("substitutions.manage"))return;const root=document.querySelector('#recommendations');root.innerHTML=result.periods.map(p=>`<div class="panel recommendation-panel" data-assignment-id="${p.assignment_id}"><h2>الحصة ${p.period} · الفصل ${esc(p.class||'—')} ${p.subject?`· ${esc(p.subject)}`:''}</h2><p>المعلم الغائب: <strong>${esc(result.absent_teacher.name)}</strong> · ${days[result.day]} ${esc(result.date)}</p><div class="assignment-fields form-grid"><label>موقع انتظار المعلم البديل<input data-waiting-location maxlength="160" placeholder="مثال: غرفة المعلمين"></label><label>ملاحظات<textarea data-assignment-notes rows="2" placeholder="ملاحظات إضافية (اختياري)"></textarea></label></div>${p.candidates.length?`<div class="candidate-list">${p.candidates.map((c,i)=>`<div class="candidate ${i===0?'best':''}"><div class="rank">${i+1}</div><div><h3>${esc(c.name)} ${i===0?'<span class="status-pill">مقترح</span>':''}</h3><p>${esc(c.specialization||'بدون تخصص مسجل')} · احتياطات اليوم: ${c.daily_assignments} · الإجمالي: ${c.historical_assignments}</p><ul>${c.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul></div><button class="button ${i===0?'primary':'secondary'}" data-action="assign" data-assignment-id="${p.assignment_id}" data-teacher-id="${c.id}">تأكيد التكليف</button></div>`).join('')}</div>`:'<div class="notice error">لا يوجد معلم متاح. تحقق من إدخال الجدول وتحديد فترات الفراغ.</div>'}</div>`).join('');root.scrollIntoView({behavior:'smooth',block:'start'})}
async function assign(id,teacher){const panel=document.querySelector(`#recommendations [data-assignment-id="${id}"]`);const location=panel?.querySelector('[data-waiting-location]').value.trim()||null,notes=panel?.querySelector('[data-assignment-notes]').value.trim()||null;try{await req(`/substitutions/${id}/assign`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({substitute_teacher_id:teacher,waiting_location:location,notes})});const candidate=allTeachers.find(x=>x.id===teacher)||teachers.find(x=>x.id===teacher);if(panel){panel.querySelector('.candidate-list')?.remove();panel.querySelector('.assignment-fields')?.remove();const success=document.createElement('div');success.className='assignment-success';success.innerHTML=`<strong>تم التكليف: ${esc(candidate?.name||'المعلم المحدد')}</strong><p>موقع الانتظار: ${esc(location||'—')}</p><p>ملاحظات: ${esc(notes||'—')}</p>`;panel.append(success)}notify('تم تسجيل التكليف وإخفاء خيارات هذه الحصة');loadAssignments();loadDashboard()}catch(e){notify(e.message,true)}}
async function loadAssignments(){const target=document.querySelector('#assignment-list');target.setAttribute('aria-busy','true');target.innerHTML=loadingMarkup('جارٍ تحميل سجل التكليفات');try{const rows=await req('/substitutions?on_date='+document.querySelector('#absence-date').value);target.innerHTML=assignmentTable(rows);target.setAttribute('aria-busy','false')}catch(e){setLoadError('#assignment-list',e,loadAssignments);notify(e.message,true)}}
function assignmentTable(rows){if(!rows?.length)return '<div class="empty">لا توجد سجلات بعد</div>';return `<div class="table-wrap"><table><thead><tr><th>الحصة</th><th>الفصل</th><th>الغائب</th><th>المكلف</th><th>موقع الانتظار</th><th>ملاحظات</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.period_number}</td><td>${esc(x.school_class?.name||'—')}</td><td>${esc(x.absent_teacher?.name||'—')}</td><td>${esc(x.substitute_teacher?.name||'—')}</td><td>${esc(x.waiting_location||'—')}</td><td>${esc(x.notes||'—')}</td><td><span class="status-pill ${x.status.toLowerCase()}">${statusLabel[x.status]||x.status}</span></td><td>${x.status==='SUGGESTED'?`<button class="button secondary" data-action="review" data-assignment-id="${x.id}" data-teacher-id="${x.absent_teacher_id}" data-date="${esc(x.date)}" data-period="${x.period_number}" data-class-id="${x.class_id||''}">عرض المرشحين</button>`:x.status==='ASSIGNED'?`<button class="button secondary" data-action="confirm" data-assignment-id="${x.id}">تأكيد</button> <button class="button secondary" data-action="complete" data-assignment-id="${x.id}">إنهاء</button> <button class="text-button" data-action="cancel" data-assignment-id="${x.id}">إلغاء</button>`:x.status==='CONFIRMED'?`<button class="button secondary" data-action="complete" data-assignment-id="${x.id}">إنهاء</button> <button class="text-button" data-action="cancel" data-assignment-id="${x.id}">إلغاء</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`}
async function reviewCandidates(id,teacherId,date,period,classId){try{const q=await req('/substitutions/suggest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({teacher_id:teacherId,date,period_number:period,class_id:classId})});renderRecommendations({absent_teacher:q.absent_teacher,date:q.date,day:q.day,periods:[{assignment_id:id,period:q.period,class:q.class,candidates:q.candidates}]})}catch(e){notify(e.message,true)}}
async function statusAction(id,action){try{await req(`/substitutions/${id}/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});notify(action==='cancel'?'تم إلغاء التكليف':action==='complete'?'تم إنهاء التكليف':'تم تأكيد التكليف');loadAssignments();loadDashboard()}catch(e){notify(e.message,true)}}
function renderTeacherList(){document.querySelector('#teacher-list').innerHTML=allTeachers.length?`<div class="table-wrap"><table><thead><tr><th>المعلم</th><th>التخصصات</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${allTeachers.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.subjects.map(s=>s.name).join('، ')||'—')}</td><td><span class="status-pill">${t.is_active?'نشط':'غير نشط'}</span></td><td><button class="button secondary" data-action="toggle-teacher" data-teacher-id="${t.id}">${t.is_active?'إيقاف':'تفعيل'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">لا يوجد معلمون بعد؛ استورد جدول المدرسة لإضافتهم تلقائيًا.</div>'}
async function loadTeachers(refresh=true){const target=document.querySelector('#teacher-list');if(refresh){target.setAttribute('aria-busy','true');target.innerHTML=loadingMarkup('جارٍ تحميل بيانات المعلمين')}try{if(refresh)await refreshBase();renderTeacherList();target.setAttribute('aria-busy','false')}catch(e){setLoadError('#teacher-list',e,()=>loadTeachers(true));notify(e.message,true)}}
