document.querySelector('#import-file').onclick=async()=>{const file=document.querySelector('#schedule-file').files[0];if(!file)return notify('اختر ملف Word أو Excel أو CSV أولًا',true);const replace=document.querySelector('#replace-master').checked;if(replace&&!confirm('سيتم استبدال الجدول وقائمة المعلمين الحالية بمحتوى الملف. سجلات الغياب والاحتياط السابقة ستبقى محفوظة. هل تريد المتابعة؟'))return;const body=new FormData();body.append('file',file);const button=document.querySelector('#import-file');button.disabled=true;button.textContent='جارٍ قراءة الملف…';try{const r=await req('/schedule/import-file?replace_existing='+replace,{method:'POST',body});await refreshBase();renderTeacherList();await Promise.all([loadSchedule(),loadDashboard()]);const loadWarning=r.load_warnings?.length?`تنبيه اختلاف عدد الحصص: ${r.load_warnings.map(w=>`${w.teacher} (${w.declared} بدل ${w.found})`).join('، ')}`:'';notify(`اكتمل الاستيراد: ${r.teachers} معلمًا، ${r.subjects} تخصصًا، ${r.classes} شعبة، و${r.imported} خانة. ${r.reserve_slots?`${r.reserve_slots} خانة احتياط (ح1 أولًا).`:''} ${loadWarning} تم تحديث قائمة المعلم الغائب.`)}catch(e){notify(e.message,true)}finally{button.disabled=false;button.textContent='قراءة واستيراد تلقائي'}};
document.querySelector('#refresh-teachers').onclick=async()=>{const button=document.querySelector('#refresh-teachers');button.disabled=true;try{await refreshBase();notify(`تم تحديث قائمة المعلمين: ${teachers.length} معلم نشط.`)}catch(e){notify(e.message,true)}finally{button.disabled=false}};
async function optimizeSchoolLogo(file){const objectUrl=URL.createObjectURL(file);try{const image=new Image();image.src=objectUrl;await image.decode();const scale=Math.min(1,1400/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);let blob=null;for(const quality of [.88,.78,.68,.58]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',quality));if(blob&&blob.size<=1_900_000)break}if(!blob||blob.size>2_000_000)throw Error('تعذر تصغير الصورة إلى الحجم المسموح');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('تعذر قراءة ملف الشعار'));reader.readAsDataURL(blob)})}catch(error){throw Error('تعذر فتح الصورة؛ جرّب صورة JPG أو PNG أو WebP. '+error.message)}finally{URL.revokeObjectURL(objectUrl)}}
function setSchoolLogoPreview(src){const image=document.querySelector('#school-logo-preview'),empty=document.querySelector('#school-logo-empty');if(src){image.src=src;image.classList.remove('hidden');empty.classList.add('hidden');image.onerror=()=>{image.classList.add('hidden');empty.textContent='تعذر تحميل الشعار؛ تحقق من الرابط';empty.classList.remove('hidden')}}else{image.removeAttribute('src');image.classList.add('hidden');empty.textContent='لم يتم تحديد شعار';empty.classList.remove('hidden')}}
async function loadSchoolSettings(){try{schoolSettings=await req('/school-settings');document.querySelector('#school-name').value=schoolSettings.school_name||'المدرسة';document.querySelector('#school-logo-url').value=schoolSettings.school_logo_url?.startsWith('data:')?'':schoolSettings.school_logo_url||'';document.querySelector('#school-logo-file').value='';setSchoolLogoPreview(schoolSettings.school_logo_url);updateSchoolIdentity()}catch(e){notify(e.message,true)}}
document.querySelector('#school-logo-url').addEventListener('input',e=>{document.querySelector('#school-logo-file').value='';schoolSettings.school_logo_url=null;setSchoolLogoPreview(e.target.value.trim())});document.querySelector('#school-logo-file').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.type==='image/svg+xml'||file.size>15_000_000){e.target.value='';notify('اختر صورة شائعة بحجم أقل من 15 ميغابايت.',true);return}document.querySelector('#school-logo-url').value='';setSchoolLogoPreview(URL.createObjectURL(file))});document.querySelector('#clear-school-logo').onclick=()=>{document.querySelector('#school-logo-url').value='';document.querySelector('#school-logo-file').value='';schoolSettings.school_logo_url=null;setSchoolLogoPreview(null)};
document.querySelector('#school-settings-form').onsubmit=async e=>{e.preventDefault();let logo=document.querySelector('#school-logo-url').value.trim()||schoolSettings.school_logo_url||null;const file=document.querySelector('#school-logo-file').files[0];try{if(file)logo=await optimizeSchoolLogo(file);schoolSettings=await req('/school-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({school_name:document.querySelector('#school-name').value,school_logo_url:logo})});document.querySelector('#school-logo-file').value='';document.querySelector('#school-logo-url').value=schoolSettings.school_logo_url?.startsWith('data:')?'':schoolSettings.school_logo_url||'';setSchoolLogoPreview(schoolSettings.school_logo_url);updateSchoolIdentity();notify('تم حفظ هوية المدرسة للطباعة')}catch(error){notify(error.message,true)}};
function buildTeacherPrintTables(){const root=document.querySelector('#schedule-table'),table=root.querySelector('table');if(!table)return null;const filtered=[...table.tBodies[0].rows].filter(row=>!row.hidden);if(!filtered.length)return null;const wrapper=document.createElement('section');wrapper.className='teacher-print-tables';wrapper.innerHTML=filtered.map(row=>{const cells=[...row.cells];const name=cells[0].innerText.trim();const periods=cells.slice(1).map((cell,index)=>`<tr><th>الحصة ${index+1}</th><td>${esc(cell.innerText.trim()||'غير مدخل')}</td></tr>`).join('');return `<article class="teacher-print-card"><h2>${esc(name)}</h2><table><thead><tr><th>الحصة</th><th>البيان</th></tr></thead><tbody>${periods}</tbody></table></article>`}).join('');return wrapper}
let currentReportData=null;
let printInProgress=false;
function buildAbsencePrintSheets(){
 const report=currentReportData;
 if(!report)return null;
 const groups=new Map();
 for(const assignment of report.assignments||[]){
  const absent=assignment.absent_teacher||{};
  const key=absent.id??absent.name??'unknown';
  if(!groups.has(key))groups.set(key,{name:absent.name||'غير محدد',assignments:[]});
  groups.get(key).assignments.push(assignment);
 }
 const ministry='<img class="absence-ministry-logo" src="/assets/ministry-of-education.png?v=3.0.0" alt="وزارة التعليم">';
 const school=`<div class="absence-school-brand">${schoolSettings.school_logo_url?`<img src="${esc(schoolSettings.school_logo_url)}" alt="شعار المدرسة">`:''}<strong>${esc(schoolSettings.school_name||report.school_name||'المدرسة')}</strong></div>`;
 const brand=`<header class="absence-sheet-branding">${ministry}${school}</header>`;
 const dayLabel=days[report.day]||({FRIDAY:'الجمعة',SATURDAY:'السبت'})[report.day]||'';
 const heading=`<h1>سجل توزيع الانتظار اليومي</h1><p class="absence-sheet-date">${esc(dayLabel)} · ${esc(report.date||'')}</p>`;
 const tableFor=items=>`<table class="absence-sheet-table"><thead><tr><th>الحصة</th><th>الفصل</th><th>موقع الانتظار</th><th>المعلم المنتظر</th><th>التوقيع</th><th>ملاحظات</th></tr></thead><tbody>${items}</tbody></table>`;
 if(!groups.size)return `<section class="absence-print-sheets"><article class="absence-print-sheet">${brand}${heading}<p class="absence-empty">لا توجد تكليفات مسجلة لهذا التاريخ.</p></article></section>`;
 const sheets=[...groups.values()].map(group=>{
  const byPeriod=new Map();
  for(const assignment of group.assignments){const period=Number(assignment.period_number)||0;if(!byPeriod.has(period))byPeriod.set(period,[]);byPeriod.get(period).push(assignment)}
  const lastPeriod=Math.max(7,...byPeriod.keys());
  const rows=Array.from({length:lastPeriod},(_,index)=>{
   const period=index+1,entries=byPeriod.get(period)||[];
   const lines=entries.length?entries:[null];
   return lines.map(assignment=>`<tr><td>${period.toLocaleString('ar-JO')}</td><td>${esc(assignment?.school_class?.name||'')}</td><td>${esc(assignment?.waiting_location||'')}</td><td>${esc(assignment?.substitute_teacher?.name||'')}</td><td class="signature-cell"></td><td>${esc(assignment?.notes||'')}</td></tr>`).join('');
  }).join('');
  return `<article class="absence-print-sheet"><p class="absence-teacher-line">إخواني المعلمين / نظراً لغياب الزميل: <strong>${esc(group.name)}</strong></p><p class="absence-instruction">هذا اليوم الموافق: ${esc(report.date||"")}، نأمل تسديد مكانه حسب الجدول الموضح والتوقيع بالعلم، ولكم مني الشكر.</p>${tableFor(rows)}</article>`;
 }).join('');
 return `<section class="absence-print-sheets">${brand}${heading}${sheets}</section>`;
}
function waitForPrintImage(image,timeout=8000){
 if(image.complete)return Promise.resolve(image.naturalWidth>0);
 return Promise.race([
  Promise.resolve().then(()=>image.decode()).then(()=>image.naturalWidth>0,()=>false),
  new Promise(resolve=>setTimeout(()=>resolve(false),timeout))
 ]);
}
async function printDocument(){
 if(printInProgress)return;
 printInProgress=true;
 const printButtons=[document.querySelector('#print-schedule'),document.querySelector('#print-report')];
 printButtons.forEach(button=>{if(button)button.disabled=true});
 const schedule=document.querySelector('#view-schedule');
 const reports=document.querySelector('#view-reports');
 const reportActive=reports.classList.contains('active');
 const originalSchedule=schedule.querySelector('#schedule-table');
 const printTables=schedule.classList.contains('active')?buildTeacherPrintTables():null;
 if(printTables)originalSchedule.after(printTables);
 const reportSheets=reportActive?buildAbsencePrintSheets():null;
 if(reportActive&&!reportSheets){printButtons.forEach(button=>{if(button)button.disabled=false});printInProgress=false;notify('حمّل التقرير أولاً قبل الطباعة.',true);return}
 if(reportSheets){reports.insertAdjacentHTML('beforeend',reportSheets);reports.classList.add('printing-report')}
 let header=null;
 if(!reportActive){
  header=document.createElement('header');
  header.className='print-branding';
  header.innerHTML=`<img class="ministry-logo" src="/assets/ministry-of-education.png?v=3.0.0" alt="وزارة التعليم"><div class="school-print-brand">${schoolSettings.school_logo_url?`<img src="${esc(schoolSettings.school_logo_url)}" alt="شعار المدرسة">`:''}<strong>${esc(schoolSettings.school_name||'المدرسة')}</strong></div>`;
  document.querySelector('.content').prepend(header);
 }
 let cleaned=false;
 const cleanup=()=>{
  if(cleaned)return;
  cleaned=true;
  header?.remove();
  printTables?.remove();
  reports.classList.remove('printing-report');
  reports.querySelector('.absence-print-sheets')?.remove();
  printButtons.forEach(button=>{if(button)button.disabled=false});
  printInProgress=false;
 };
 const printImages=[...document.querySelectorAll('.print-branding img,.absence-print-sheets img')];
 const imageResults=await Promise.all(printImages.map(async image=>{
  image.loading='eager';
  image.decoding='sync';
  return {image,ready:await waitForPrintImage(image)};
 }));
 const failedImage=imageResults.find(result=>!result.ready)?.image;
 if(failedImage){cleanup();notify(failedImage.alt==='وزارة التعليم'?'تعذر تحميل شعار وزارة التعليم؛ حدّث الصفحة ثم حاول الطباعة مجددًا.':'تعذر تحميل شعار المدرسة؛ تحقق من رابط الشعار ثم حاول الطباعة مجددًا.',true);return}
 window.addEventListener('afterprint',cleanup,{once:true});
 try{window.print()}catch(error){cleanup();notify('تعذر فتح نافذة الطباعة؛ حاول مرة أخرى.',true)}
}
document.querySelector('#print-schedule').onclick=printDocument;document.querySelector('#print-report').onclick=printDocument;
async function loadReport(){const d=document.querySelector('#report-date').value,target=document.querySelector('#report-data');target.setAttribute('aria-busy','true');target.innerHTML=loadingMarkup('جارٍ تجهيز التقرير');try{const r=await req('/reports/daily-substitutions?on_date='+d);const assignments=r.assignments||[];currentReportData={...r,assignments};const assigned=assignments.filter(x=>['ASSIGNED','CONFIRMED','COMPLETED'].includes(x.status)).length;const pending=assignments.filter(x=>x.status==='SUGGESTED').length;target.innerHTML=`<p class="report-heading-label">تقرير الاحتياط اليومي</p><div class="panel-heading"><div><h2>${esc(r.school_name)} · ${days[r.day]||({FRIDAY:'الجمعة',SATURDAY:'السبت'})[r.day]||''}</h2><p class="muted">${esc(r.date)} · ${assignments.length} حصة متأثرة</p></div><span class="panel-icon">${uiIcon('file')}</span></div><div class="report-summary"><span><strong>${assignments.length}</strong> حصص متأثرة</span><span><strong>${assigned}</strong> حصص مسندة</span><span><strong>${pending}</strong> بانتظار الإسناد</span></div>${assignments.length?`<div class="table-wrap"><table><thead><tr><th>الحصة</th><th>الفصل</th><th>المعلم الغائب</th><th>المعلم البديل</th><th>الحالة</th><th>موقع الانتظار</th><th>ملاحظات</th></tr></thead><tbody>${assignments.map(a=>`<tr><td>${a.period_number}</td><td>${esc(a.school_class?.name||'—')}</td><td>${esc(a.absent_teacher?.name||'—')}</td><td>${esc(a.substitute_teacher?.name||'—')}</td><td><span class="status-pill ${a.status.toLowerCase()}">${statusLabel[a.status]||a.status}</span></td><td>${esc(a.waiting_location||'—')}</td><td>${esc(a.notes||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">لا توجد تكليفات مسجلة لهذا التاريخ</div>'}`;target.setAttribute('aria-busy','false')}catch(e){currentReportData=null;setLoadError('#report-data',e,loadReport);notify(e.message,true)}}
const auditEntityLabel={role:'دور',staff_account:'حساب موظف',absence:'غياب',substitution:'احتياط',schedule:'جدول',teacher:'معلم',subject:'مادة',class:'شعبة'};
const auditActionLabel={UPDATED:'تعديل',DELETED:'حذف',INVITED:'دعوة',DEACTIVATED:'إيقاف',CREATED:'إنشاء',IMPORTED:'استيراد',ASSIGNED:'إسناد',CONFIRMED:'تأكيد',COMPLETED:'إنهاء',CANCELLED:'إلغاء'};
async function loadAudit(){const target=document.querySelector('#audit-list');if(!target)return;const filter=document.querySelector('#audit-entity').value;target.setAttribute('aria-busy','true');target.innerHTML=loadingMarkup('جارٍ تحميل سجل التدقيق');try{const rows=await req('/audit'+(filter?'?entity_type='+encodeURIComponent(filter):''));target.innerHTML=rows?.length?`<div class="table-wrap"><table><thead><tr><th>الوقت</th><th>النوع</th><th>الإجراء</th><th>المسؤول</th><th>التفاصيل</th></tr></thead><tbody>${rows.map(row=>{const date=row.created_at?new Date(row.created_at):null;const dateLabel=date&&!Number.isNaN(date.getTime())?new Intl.DateTimeFormat('ar-JO',{dateStyle:'medium',timeStyle:'short'}).format(date):'—';return `<tr><td>${esc(dateLabel)}</td><td>${esc(auditEntityLabel[row.entity_type]||row.entity_type||'—')} <span class="muted">#${esc(row.entity_id??'—')}</span></td><td><span class="status-pill">${esc(auditActionLabel[row.action]||row.action||'—')}</span></td><td>${esc(row.actor||'—')}</td><td>${esc(row.detail||'—')}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty"><strong>لا توجد إجراءات مسجلة</strong><br>ستظهر هنا العمليات التي تم تنفيذها على بيانات المدرسة.</div>';target.setAttribute('aria-busy','false')}catch(e){setLoadError('#audit-list',e,loadAudit);notify(e.message,true)}}
document.querySelector('#audit-entity').onchange=loadAudit;document.querySelector('#refresh-audit').onclick=loadAudit;
function addAssistantMessage(message,kind='bot'){
 const log=document.querySelector('#assistant-messages');
 const item=document.createElement('article');item.className=`assistant-message ${kind}`;
 if(kind==='bot'){const avatar=document.createElement('span');avatar.className='assistant-message-avatar';avatar.setAttribute('aria-hidden','true');avatar.textContent='ب';item.append(avatar)}
 const body=document.createElement('p');body.textContent=message;item.append(body);log.append(item);log.scrollTop=log.scrollHeight;
}
function resetAssistantConversation(message='مساعد بديل قيد التطوير حاليًا. بنرجع نفعّله قريبًا، شكرًا لانتظارك.'){
 assistantConversation=[];const log=document.querySelector('#assistant-messages');log.replaceChildren();addAssistantMessage(message);
}
function askAssistant(){
 resetAssistantConversation();
}
document.querySelector('#assistant-form').addEventListener('submit',event=>{event.preventDefault();resetAssistantConversation()});
document.querySelectorAll('[data-assistant-question]').forEach(button=>button.addEventListener('click',()=>askAssistant(button.dataset.assistantQuestion)));
document.querySelector('#assistant-clear').addEventListener('click',()=>{resetAssistantConversation();document.querySelector('#assistant-question').focus()});
document.addEventListener('pointerdown',event=>{if(!assistantPanel.hidden&&!assistantWidget.contains(event.target))toggleAssistant(false,false)});
const assistantWidget=document.querySelector('#assistant-widget'),assistantPanel=document.querySelector('#assistant-panel'),assistantToggle=document.querySelector('#assistant-toggle');
let assistantDrag=null,assistantDidDrag=false;
function positionAssistantPanel(){
 if(assistantPanel.hidden)return;
 const toggleRect=assistantToggle.getBoundingClientRect(),panelRect=assistantPanel.getBoundingClientRect(),gap=12,pad=10;
 const left=Math.max(pad,Math.min(toggleRect.right-panelRect.width,window.innerWidth-panelRect.width-pad));
 let top=toggleRect.top-panelRect.height-gap;
 if(top<pad)top=Math.min(window.innerHeight-panelRect.height-pad,toggleRect.bottom+gap);
 assistantPanel.style.left=`${left}px`;assistantPanel.style.top=`${Math.max(pad,top)}px`;assistantPanel.style.right='auto';assistantPanel.style.bottom='auto';
}
function toggleAssistant(force,restoreFocus=true){
 const open=typeof force==='boolean'?force:assistantPanel.hidden;
 assistantPanel.hidden=!open;assistantToggle.setAttribute('aria-expanded',String(open));
 if(open){resetAssistantConversation();positionAssistantPanel();requestAnimationFrame(()=>document.querySelector('#assistant-close').focus())}
 else if(restoreFocus)assistantToggle.focus();
}
assistantToggle.addEventListener('click',()=>{if(assistantDidDrag){assistantDidDrag=false;return}toggleAssistant()});
document.querySelector('#assistant-close').addEventListener('click',()=>toggleAssistant(false));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!assistantPanel.hidden)toggleAssistant(false)});
window.addEventListener('resize',positionAssistantPanel);
assistantToggle.addEventListener('pointerdown',event=>{
 if(event.button!==0)return;
 const rect=assistantWidget.getBoundingClientRect();assistantDrag={pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,offsetX:event.clientX-rect.left,offsetY:event.clientY-rect.top,moved:false};assistantToggle.setPointerCapture(event.pointerId);
});
assistantToggle.addEventListener('pointermove',event=>{
 if(!assistantDrag||event.pointerId!==assistantDrag.pointerId)return;
 const dx=event.clientX-assistantDrag.startX,dy=event.clientY-assistantDrag.startY;
 if(!assistantDrag.moved&&Math.hypot(dx,dy)<6)return;
 assistantDrag.moved=true;assistantDidDrag=true;
 const left=Math.max(8,Math.min(window.innerWidth-assistantWidget.offsetWidth-8,event.clientX-assistantDrag.offsetX));
 const top=Math.max(8,Math.min(window.innerHeight-assistantWidget.offsetHeight-8,event.clientY-assistantDrag.offsetY));
 assistantWidget.style.left=`${left}px`;assistantWidget.style.top=`${top}px`;assistantWidget.style.right='auto';assistantWidget.style.bottom='auto';
 if(!assistantPanel.hidden)positionAssistantPanel();event.preventDefault();
});
function finishAssistantDrag(event){if(!assistantDrag||event.pointerId!==assistantDrag.pointerId)return;const moved=assistantDrag.moved;assistantDrag=null;if(moved)setTimeout(()=>{assistantDidDrag=false},0)}
assistantToggle.addEventListener('pointerup',finishAssistantDrag);assistantToggle.addEventListener('pointercancel',finishAssistantDrag);

