function applyRoleNavigation(){document.querySelectorAll('.nav').forEach(b=>b.hidden=!canView(b.dataset.view)||(b.dataset.view==='my-work'&&currentRole==='MANAGER'));document.body.classList.toggle('read-only-schedule',!can('schedule.edit'));applyPermissionControls()}
async function loadMyWork() {
  const scheduleTarget=document.querySelector('#my-schedule');
  const assignmentTarget=document.querySelector('#my-assignments');
  scheduleTarget.setAttribute('aria-busy','true');
  assignmentTarget.setAttribute('aria-busy','true');
  scheduleTarget.innerHTML=loadingMarkup('جارٍ تحميل جدولك');
  assignmentTarget.innerHTML=loadingMarkup('جارٍ تحميل تكليفاتك');
  try {
    const day=document.querySelector('#my-schedule-day').value;
    const date=document.querySelector('#my-assignments-date').value;
    const [entries,assignments]=await Promise.all([
      req('/staff/me/schedule'+(day?'?day='+day:'')),
      req('/staff/me/assignments'+(date?'?on_date='+date:''))
    ]);
    scheduleTarget.innerHTML=personalScheduleMarkup(entries);
    assignmentTarget.innerHTML=personalAssignmentsMarkup(assignments);
    scheduleTarget.setAttribute('aria-busy','false');
    assignmentTarget.setAttribute('aria-busy','false');
  } catch(e) {
    setLoadError('#my-schedule',e,loadMyWork);
    assignmentTarget.innerHTML='';
    assignmentTarget.setAttribute('aria-busy','false');
  }
}
async function loadStaff(){const target=document.querySelector('#staff-list');target.innerHTML=loadingMarkup('جارٍ تحميل فريق المدرسة');try{const [rows,staffTeachers,catalog]=await Promise.all([req('/staff'),req('/teachers?active_only=true'),req('/roles')]);staffRows=rows;roleCatalog=catalog;const select=document.querySelector('#staff-teacher');const available=staffTeachers.filter(t=>!rows.some(r=>r.teacher_id===t.id));select.innerHTML=available.length?available.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join(''):'<option value="">أضف معلمًا جديدًا لدعوته</option>';select.disabled=!available.length;document.querySelector('#staff-form button[type=submit],#staff-form button').disabled=!available.length;document.querySelector('#staff-role').innerHTML=roleOptions();renderStaffRows()}catch(e){setLoadError('#staff-list',e,loadStaff)}}
async function deactivateStaff(id){if(!confirm('إيقاف حساب الموظف؟ لن يتمكن من تسجيل الدخول.'))return;try{await req('/staff/'+id,{method:'DELETE'});notify('تم إيقاف حساب الموظف');loadStaff()}catch(e){notify(e.message,true)}}

async function updateStaffRole(id){try{await req('/staff/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(rolePayload(document.querySelector('#staff-role-'+id).value))});notify('تم تحديث رتبة الموظف');loadStaff()}catch(e){notify(e.message,true)}}
async function resendStaffInvite(id){try{await req('/staff/'+id+'/resend-invite',{method:'POST'});notify('تم إرسال رابط تفعيل جديد إلى البريد');loadStaff()}catch(e){notify(e.message,true)}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const id=Number(button.dataset.assignmentId||0),teacherId=Number(button.dataset.teacherId||0);switch(button.dataset.action){case'assign':assign(id,teacherId);break;case'review':reviewCandidates(id,teacherId,button.dataset.date,Number(button.dataset.period),Number(button.dataset.classId)||null);break;case'confirm':case'complete':case'cancel':statusAction(id,button.dataset.action);break;case'toggle-teacher':toggleTeacher(teacherId);break;case'update-staff-role':updateStaffRole(Number(button.dataset.staffId));break;case'deactivate-staff':deactivateStaff(Number(button.dataset.staffId));break;case'resend-staff-invite':resendStaffInvite(Number(button.dataset.staffId));break}});
