function showAuth(registerAllowed,error='',mode='login',username='',messageType='error',inviteToken=''){registrationAvailable=registerAllowed;authMode=mode;if(inviteToken)pendingStaffInvite=inviteToken;document.querySelector('#app-shell').classList.add('hidden');document.querySelector('#auth-screen').classList.remove('hidden');document.querySelector('#register-form').classList.toggle('hidden',authMode!=='register');document.querySelector('#login-form').classList.toggle('hidden',authMode!=='login');document.querySelector('#activation-form').classList.toggle('hidden',authMode!=='activate');document.querySelector('#staff-invite-form').classList.toggle('hidden',authMode!=='staff-invite');document.querySelector('#auth-title').textContent=authMode==='register'?'إنشاء حساب جديد':authMode==='activate'?'تفعيل الحساب':authMode==='staff-invite'?'تفعيل حساب الموظف':'تسجيل الدخول';document.querySelector('#auth-copy').textContent=authMode==='register'?'أنشئ حسابًا وسيصلك مفتاح التفعيل عبر البريد الإلكتروني.':authMode==='activate'?'أدخل مفتاح التفعيل الذي أرسلناه إلى بريدك.':authMode==='staff-invite'?'أنشأ مدير مدرستك حسابًا لك. اختر كلمة مرور لإكمال التفعيل.':'سجّل الدخول بحسابك المحفوظ.';document.querySelector('#activation-username').textContent=username?`الحساب: ${username}`:'';const toggle=document.querySelector('#auth-toggle');toggle.classList.toggle('hidden',!registerAllowed||authMode==='activate'||authMode==='staff-invite');toggle.textContent=authMode==='register'?'لديك حساب؟ تسجيل الدخول':'إنشاء حساب جديد';const box=document.querySelector('#auth-error');box.textContent=error;box.classList.toggle('hidden',!error);box.classList.toggle('error',messageType!=='success');box.classList.toggle('success',messageType==='success')}
async function activateApp(){document.querySelector('#app-shell').classList.add('hidden');resetAssistantConversation('أهلًا! اسألني عن جدول معلم أو شعبة، الغياب، الاحتياط، أو المعلمين المتاحين.');try{const profile=await req('/staff/me');currentRole=profile.role;assistantHasTeacherProfile=Boolean(profile.teacher_id);document.querySelectorAll('[data-assistant-personal]').forEach(button=>button.hidden=!assistantHasTeacherProfile);currentPermissions=new Set(profile.permissions||[]);document.body.dataset.role=currentRole;document.querySelector('#account-badge').textContent=profile.role_name+' · '+profile.username;applyRoleNavigation();allTeachers=[];teachers=[];subjects=[];classes=[];if(can('directory.view'))await refreshBase();await loadSchoolSettings();const first=['dashboard','schedule','substitutions','reports','teachers','my-work'].find(canView);view(first);document.querySelector('#auth-screen').classList.add('hidden');document.querySelector('#app-shell').classList.remove('hidden')}catch(e){showAuth(registrationAvailable,'تعذر تحميل البيانات: '+e.message)}}
async function authRequest(path,payload){const r=await fetch(API+'/auth/'+path,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(payload)});const data=await r.json().catch(()=>({}));if(!r.ok){const detail=typeof data.detail==='string'?data.detail:Array.isArray(data.detail)?data.detail[0]?.msg?.replace(/^Value error,\s*/i,''):'';throw Error(detail||'تعذر تنفيذ الطلب')}return data}
document.querySelectorAll('.password-toggle').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.passwordTarget);const reveal=input.type==='password';input.type=reveal?'text':'password';button.textContent=reveal?'إخفاء':'إظهار';button.setAttribute('aria-label',reveal?'إخفاء كلمة المرور':'إظهار كلمة المرور');button.setAttribute('aria-pressed',String(reveal))}));
function randomPasswordIndex(max){const limit=0x100000000-(0x100000000%max),buffer=new Uint32Array(1);do{crypto.getRandomValues(buffer)}while(buffer[0]>=limit);return buffer[0]%max}
function makeSuggestedPassword(){const groups=['ABCDEFGHJKLMNPQRSTUVWXYZ','abcdefghijkmnopqrstuvwxyz','23456789','!@#$%&*+-_'];const all=groups.join('');const chars=groups.map(group=>group[randomPasswordIndex(group.length)]);while(chars.length<18)chars.push(all[randomPasswordIndex(all.length)]);for(let i=chars.length-1;i>0;i--){const j=randomPasswordIndex(i+1);[chars[i],chars[j]]=[chars[j],chars[i]]}return chars.join('')}
document.querySelector('#suggest-password').addEventListener('click',()=>{try{const password=makeSuggestedPassword();for(const id of ['register-password','register-password-confirm']){const input=document.getElementById(id);input.value=password;input.dispatchEvent(new Event('input',{bubbles:true}))}}catch(error){notify('تعذر اقتراح كلمة مرور آمنة في هذا المتصفح.',true)}});
document.querySelector('#auth-toggle').onclick=()=>showAuth(registrationAvailable,'',authMode==='register'?'login':'register');
document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const username=document.querySelector('#login-username').value;if(/\s/u.test(username)){showAuth(registrationAvailable,'اسم المستخدم لا يقبل أي مسافات أو فراغات','login');return}try{const result=await authRequest('login',{username,password:document.querySelector('#login-password').value});if(result.activation_required)showAuth(registrationAvailable,'','activate',result.username);else await activateApp()}catch(error){showAuth(registrationAvailable,error.message,'login')}};
document.querySelector('#register-form').onsubmit=async e=>{e.preventDefault();const username=document.querySelector('#register-username').value;if(/\s/u.test(username)){showAuth(registrationAvailable,'اسم المستخدم لا يقبل أي مسافات أو فراغات','register');return}try{await authRequest('register',{school_name:document.querySelector('#register-school-name').value,username,email:document.querySelector('#register-email').value,password:document.querySelector('#register-password').value,confirm_password:document.querySelector('#register-password-confirm').value});showAuth(registrationAvailable,'تم إنشاء الحساب وإرسال مفتاح التفعيل إلى بريدك الإلكتروني. سجّل الدخول لإكمال التفعيل.','login','','success')}catch(error){showAuth(registrationAvailable,error.message,'register')}};
document.querySelector('#staff-invite-form').onsubmit=async e=>{e.preventDefault();try{await authRequest('accept-staff-invite',{token:pendingStaffInvite,password:document.querySelector('#staff-invite-password').value,confirm_password:document.querySelector('#staff-invite-password-confirm').value});pendingStaffInvite='';await activateApp()}catch(error){showAuth(registrationAvailable,error.message,'staff-invite','','error',pendingStaffInvite)}};
document.querySelector('#activation-form').onsubmit=async e=>{e.preventDefault();try{await authRequest('activate-license',{license_key:document.querySelector('#activation-key').value});await activateApp()}catch(error){showAuth(registrationAvailable,error.message,'activate',document.querySelector('#activation-username').textContent.replace(/^الحساب:\s*/,''))}};
document.querySelector('#logout').onclick=async()=>{try{await req('/auth/logout',{method:'POST'});closeNavigation();showAuth(registrationAvailable)}catch(e){showAuth(false)}};
async function start(){try{const invite=new URLSearchParams(location.hash.replace(/^#/,'')).get('staff_invite');if(invite){pendingStaffInvite=invite;history.replaceState(null,'',location.pathname+location.search)}const r=await fetch(API+'/auth/status',{credentials:'include'});const status=await r.json();registrationAvailable=Boolean(status.registration_available);if(invite){showAuth(registrationAvailable,'','staff-invite','','error',invite);return}if(status.authenticated)await activateApp();else if(status.activation_required)showAuth(registrationAvailable,'','activate',status.username);else showAuth(registrationAvailable)}catch(e){showAuth(false,'تعذر الاتصال بالخادم: '+e.message)}}start();
